import{_ as n,K as p,a as o,c,ac as r,q as a,b as t,k as d}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"计算机网络原理（04735） · IP、子网与路由：跨网络送达主机至传输层：端口、可靠交付与连接","description":"按分层、链路、IP路由、传输与应用学习，配合子网/分片计算和连接流程图。","frontmatter":{"title":"计算机网络原理（04735） · IP、子网与路由：跨网络送达主机至传输层：端口、可靠交付与连接","description":"按分层、链路、IP路由、传输与应用学习，配合子网/分片计算和连接流程图。","splitFrom":"principles/network-principles/internetprinciples.md","showdocs":{"topics":[{"id":"network-principles","title":"计算机网络原理","link":"/topics/network-principles/"},{"id":"network","title":"网络配置与诊断","link":"/topics/network/"}],"kind":"故障边界与规范","scope":"general","audience":"general","group":"原理与设计","seriesTitle":"计算机网络原理（04735）","summary":"按分层、链路、IP路由、传输与应用学习，配合子网/分片计算和连接流程图。","status":"active","related":[{"title":"计算机网络原理（04735）","link":"/principles/network-principles/internetprinciples","kind":"故障边界与规范","scope":"general","audience":"general"},{"title":"计算机网络原理（04735） · 先建立分层与交换的整体认识至物理与链路：先让相邻节点通信","link":"/principles/network-principles/internetprinciples-part-01","kind":"故障边界与规范","scope":"general","audience":"general"},{"title":"计算机网络原理（04735） · 应用层：从域名到服务至协议参考","link":"/principles/network-principles/internetprinciples-part-03","kind":"故障边界与规范","scope":"general","audience":"general"},{"title":"长度前缀分帧与粘包拆包练习","link":"/principles/network-principles/application","kind":"应用分帧推演","scope":"general","audience":"general"},{"title":"TCP字节流、可靠传输与网络排错","link":"/principles/network-principles/tcp-and-network-diagnosis","kind":"层次与端到端机制","scope":"general","audience":"general"}],"prev":{"text":"计算机网络原理（04735） · 先建立分层与交换的整体认识至物理与链路：先让相邻节点通信","link":"/principles/network-principles/internetprinciples-part-01"},"next":{"text":"计算机网络原理（04735） · 应用层：从域名到服务至协议参考","link":"/principles/network-principles/internetprinciples-part-03"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"计算机网络原理（04735） · 先建立分层与交换的整体认识至物理与链路：先让相邻节点通信","link":"/principles/network-principles/internetprinciples-part-01"},"next":{"text":"计算机网络原理（04735） · 应用层：从域名到服务至协议参考","link":"/principles/network-principles/internetprinciples-part-03"}},"headers":[],"relativePath":"principles/network-principles/internetprinciples-part-02.md","filePath":"principles/network-principles/internetprinciples-part-02.md"}'),l={name:"principles/network-principles/internetprinciples-part-02.md"};function s(I,e,h,P,u,T){const i=p("Mermaid");return o(),c("div",null,[e[0]||(e[0]=r('<h1 id="计算机网络原理-04735-·-ip、子网与路由-跨网络送达主机至传输层-端口、可靠交付与连接" tabindex="-1">计算机网络原理（04735） · IP、子网与路由：跨网络送达主机至传输层：端口、可靠交付与连接 <a class="header-anchor" href="#计算机网络原理-04735-·-ip、子网与路由-跨网络送达主机至传输层-端口、可靠交付与连接" aria-label="Permalink to &quot;计算机网络原理（04735） · IP、子网与路由：跨网络送达主机至传输层：端口、可靠交付与连接&quot;">​</a></h1><p><a href="/principles/network-principles/internetprinciples">返回分篇目录</a></p><p>按“分层与性能 → 链路 → IP 与路由 → 传输 → 应用”的顺序理解一次请求，再补充无线与安全。历史课程中的电路交换、PPP、经典共享以太网等保留为原理对照，不与现代网络部署混写。</p><h2 id="ip-routing" tabindex="-1">IP、子网与路由：跨网络送达主机 <a class="header-anchor" href="#ip-routing" aria-label="Permalink to &quot;IP、子网与路由：跨网络送达主机 {#ip-routing}&quot;">​</a></h2><h3 id="ip-服务、转发与最长前缀匹配" tabindex="-1">IP 服务、转发与最长前缀匹配 <a class="header-anchor" href="#ip-服务、转发与最长前缀匹配" aria-label="Permalink to &quot;IP 服务、转发与最长前缀匹配 {#ip-服务、转发与最长前缀匹配}&quot;">​</a></h3><p>目的192.0.2.130同时匹配默认路由、192.0.2.0/24与192.0.2.128/25时，选/25，因为其约束的前缀位最多。更长前缀不是更短网络距离，而是更具体的地址匹配。</p>',6)),a(i,{source:"Zmxvd2NoYXJ0IFRECiBBWyLnm67nmoQxOTIuMC4yLjEzMCJdIC0tPiBCWyLljLnphY0wLjAuMC4wLzAiXQogQSAtLT4gQ1si5Yy56YWNMTkyLjAuMi4wLzI0Il0KIEEgLS0+IERbIuWMuemFjTE5Mi4wLjIuMTI4LzI1Il0KIEQgLS0+IEVbIumAieacgOmVv+eahDI15L2N5YmN57yA5a+55bqU5LiL5LiA6LezIl0K"}),e[1]||(e[1]=r('<p>IP 提供尽力而为的数据报传送，不保证到达、顺序或无重复。转发是在本节点为当前包选择输出，路由是计算与维护可达路径；两者职责不同。</p><p>路由器包含输入处理、交换结构、输出排队和控制处理。内存、总线或交换网络是交换结构实现方式；性能应按具体设计衡量，不能只凭分类断言价格高低。</p><p>转发表中多条路由匹配时，采用最长前缀匹配；没有更具体匹配才考虑默认路由。完全无路由时不能凭空转发。</p><h3 id="ipv4-地址、cidr-与子网计算" tabindex="-1">IPv4 地址、CIDR 与子网计算 <a class="header-anchor" href="#ipv4-地址、cidr-与子网计算" aria-label="Permalink to &quot;IPv4 地址、CIDR 与子网计算 {#ipv4-地址、cidr-与子网计算}&quot;">​</a></h3><p>IPv4 地址为 32 位；CIDR 写作 <code>地址/前缀长度</code>。网络号由地址与掩码按位与得到，传统 A/B/C 分类用于理解历史编址，实际规划应按前缀计算。</p><table tabindex="0"><thead><tr><th>地址用途</th><th>范围或示例</th></tr></thead><tbody><tr><td>私有地址</td><td><code>10.0.0.0/8</code>、<code>172.16.0.0/12</code>、<code>192.168.0.0/16</code></td></tr><tr><td>回环</td><td><code>127.0.0.0/8</code>，常用 <code>127.0.0.1</code></td></tr><tr><td>未指定地址</td><td><code>0.0.0.0</code>，含义随地址字段与使用场景确定</td></tr><tr><td>有限广播</td><td><code>255.255.255.255</code></td></tr></tbody></table><p>以 <code>203.123.1.135/26</code> 为例：</p><ol><li>掩码为 <code>255.255.255.192</code>，主机位 6 位，共 <code>2^6=64</code> 个地址。</li><li>所属网络为 <code>203.123.1.128/26</code>，广播地址 <code>203.123.1.191</code>。</li><li>普通广播子网可用主机范围为 <code>.129</code> 至 <code>.190</code>，62 个地址。</li></ol><p>“地址总数减二”适用于这类普通子网，不直接套用到 <code>/31</code> 点对点或 <code>/32</code> 路由。路由聚合还要求地址块连续、对齐，且聚合后的下一跳行为符合要求。</p><h3 id="mtu、ipv4-分片与-icmp" tabindex="-1">MTU、IPv4 分片与 ICMP <a class="header-anchor" href="#mtu、ipv4-分片与-icmp" aria-label="Permalink to &quot;MTU、IPv4 分片与 ICMP {#mtu、ipv4-分片与-icmp}&quot;">​</a></h3><p>本例每片都带独立20字节首部，片间偏移按原载荷计算。前两片载荷1480能被8整除，最后一片420不要求再按8补齐；重组必须等相应片段到达。</p>',11)),a(i,{source:""}),e[2]||(e[2]=r('<p>MTU 是链路能承载的网络层包上限；IPv4 首部通常至少 20 字节，分片偏移以 8 字节为单位。DF 表示不允许分片，MF 表示后续还有分片。最终由目的主机重组，不能把分片当成提高吞吐的常规手段。</p><p>例：总长度 3400 字节、无选项首部 20 字节、MTU 1500，载荷共 3380 字节；可拆成 1480、1480、420 字节载荷。总长度分别为 1500、1500、440，偏移为 0、185、370，MF 为 1、1、0。</p><p>ICMP 承担差错与诊断，如不可达、超时和 Echo；<code>ping</code> 结果不能单独证明某个应用端口可用。历史“源点抑制”消息不能作为现代拥塞控制的推荐机制。</p><h3 id="dhcp、nat、ipv6-与路由协议" tabindex="-1">DHCP、NAT、IPv6 与路由协议 <a class="header-anchor" href="#dhcp、nat、ipv6-与路由协议" aria-label="Permalink to &quot;DHCP、NAT、IPv6 与路由协议 {#dhcp、nat、ipv6-与路由协议}&quot;">​</a></h3><p>DHCP 为主机提供地址、掩码、网关等配置；典型 IPv4 流程为发现、提供、请求、确认，使用 UDP 67/68。NAT 维护内部与外部地址/端口映射；外部主动访问需要额外映射或穿透设计，NAT 不等于安全策略。</p><p>IPv6 地址为 128 位，基本首部 40 字节；用冒号分隔的十六进制组表示，连续零压缩 <code>::</code> 至多出现一次。它没有 IPv4 式广播，邻居发现也不使用 ARP。双栈与隧道是不同迁移策略。</p><table tabindex="0"><thead><tr><th>路由机制</th><th>思想或范围</th></tr></thead><tbody><tr><td>链路状态</td><td>传播拓扑信息，计算最短路径，如 OSPF</td></tr><tr><td>距离向量</td><td>与邻居交换距离估计，基于 Bellman-Ford 思路，如 RIP</td></tr><tr><td>分层路由</td><td>以自治系统 AS 等边界限制规模与管理范围</td></tr><tr><td>BGP</td><td>交换自治系统间可达性及路径属性，受路由策略影响</td></tr></tbody></table><p>RIP 用跳数度量，16 表示不可达；OSPF 支持区域与等价路径；BGP 通过 TCP 179 建立会话，关注 <code>AS_PATH</code>、<code>NEXT_HOP</code> 等属性，不只是选择物理最短路。OPEN、UPDATE、KEEPALIVE、NOTIFICATION 分别承担建会话、更新、保活和错误通知。</p><p><span id="第三章-传输层" aria-hidden="true"></span><span id="_1-传输层的基本服务" aria-hidden="true"></span><span id="_2-传输层的复用与分解" aria-hidden="true"></span><span id="_3-停-等协议与滑动窗口协议" aria-hidden="true"></span><span id="_4-用户数据包协议-udp-user-datagram-protocol" aria-hidden="true"></span><span id="_5-传输控制协议-transmission-control-protocol-tcp" aria-hidden="true"></span></p><h2 id="transport" tabindex="-1">传输层：端口、可靠交付与连接 <a class="header-anchor" href="#transport" aria-label="Permalink to &quot;传输层：端口、可靠交付与连接 {#transport}&quot;">​</a></h2><h3 id="tcp-与-udp-的边界" tabindex="-1">TCP 与 UDP 的边界 <a class="header-anchor" href="#tcp-与-udp-的边界" aria-label="Permalink to &quot;TCP 与 UDP 的边界 {#tcp-与-udp-的边界}&quot;">​</a></h3><p>端口号为 16 位；TCP 连接通常由源/目的 IP 与源/目的端口四元组区分。端口范围区分熟知、登记与动态端口，不代表客户端或服务端在技术上只能使用某段范围。</p><table tabindex="0"><thead><tr><th>协议</th><th>提供什么</th><th>应用需考虑什么</th></tr></thead><tbody><tr><td>TCP</td><td>面向连接、有序可靠的字节流、流量与拥塞控制</td><td>应用消息边界、超时、连接中断与业务重试</td></tr><tr><td>UDP</td><td>数据报、端口复用及校验等基础能力</td><td>丢失、重复、乱序以及是否自行实现可靠性/拥塞控制</td></tr></tbody></table><p>UDP 首部 8 字节，TCP 基本首部通常 20 字节，选项会增加长度。可靠字节流不代表业务一定成功：连接断开后应用仍需判断处理结果与幂等性。</p><h3 id="停等、gbn-与选择重传" tabindex="-1">停等、GBN 与选择重传 <a class="header-anchor" href="#停等、gbn-与选择重传" aria-label="Permalink to &quot;停等、GBN 与选择重传 {#停等、gbn-与选择重传}&quot;">​</a></h3><p>可靠交付需要组合差错检测、序号、确认与重传计时器。停等一次只等待一个未确认分组，逻辑简单但长时延链路利用率低；滑动窗口允许流水发送。</p><table tabindex="0"><thead><tr><th>协议</th><th>接收行为</th><th>重传行为</th></tr></thead><tbody><tr><td>停等</td><td>按序接收，区分新旧分组</td><td>等待确认或超时重发</td></tr><tr><td>GBN</td><td>典型接收窗口为 1，丢弃乱序包</td><td>累计确认，超时重发一段未确认分组</td></tr><tr><td>SR</td><td>缓存窗口内乱序包，逐个确认</td><td>只重传未确认的分组</td></tr></tbody></table><p>序号空间必须与窗口大小协调，防止旧包与新包混淆。TCP 借鉴这些机制，但不是把教材中的 GBN 或 SR 原封不动套用。</p><p>假设发送方窗口允许发送 1、2、3、4，分组 2 丢失，3、4 正常到达：</p><ul><li><strong>GBN</strong>：接收方只接纳下一个按序分组，因此丢弃 3、4，继续累计确认到 1。发送方通常为最早未确认分组维护一个计时器；2 超时后重发 2、3、4。收到累计确认到 n 后，发送窗口左沿推进到 n＋1。</li><li><strong>SR</strong>：接收方缓存窗口内的 3、4 并分别确认；发送方标记它们已确认，但窗口左沿仍等 2。每个待确认分组各有逻辑计时，2 超时只重发 2；收到它的确认后，左沿可连续越过已确认的 2、3、4。接收方此时也可把连续序列交给上层。</li></ul><p>ACK 丢失还需要重发确认与去重处理。这里的“每包计时”是协议逻辑，不要求实现必须为每个包创建一个操作系统定时器。</p><h3 id="tcp-序号、三次握手与关闭" tabindex="-1">TCP 序号、三次握手与关闭 <a class="header-anchor" href="#tcp-序号、三次握手与关闭" aria-label="Permalink to &quot;TCP 序号、三次握手与关闭 {#tcp-序号、三次握手与关闭}&quot;">​</a></h3><p>TCP 按字节编号，累计确认号表示下一期待的字节；SYN 与 FIN 各消耗一个序号。连接建立的典型过程：</p>',23)),a(i,{source:"c2VxdWVuY2VEaWFncmFtCiAgICBwYXJ0aWNpcGFudCBDIGFzIOWuouaIt+errwogICAgcGFydGljaXBhbnQgUyBhcyDmnI3liqHnq68KICAgIEMtPj5TOiBTWU4gc2VxPXgKICAgIFMtLT4+QzogU1lOK0FDSyBzZXE9eSBhY2s9eCsxCiAgICBDLT4+UzogQUNLIHNlcT14KzEgYWNrPXkrMQo="}),e[3]||(e[3]=t("p",null,[d("客户端经过 "),t("code",null,"SYN-SENT"),d("，服务端经过 "),t("code",null,"SYN-RECEIVED"),d(" 后进入 "),t("code",null,"ESTABLISHED"),d("。握手同步双方序号并确认连接状态；第三步可以携带数据。")],-1)),e[4]||(e[4]=t("p",null,"关闭时两个方向分别结束。以下假定对端在收到 FIN 后又发送了数据，最后一个数据字节之后的序号是 w：",-1)),a(i,{source:"c2VxdWVuY2VEaWFncmFtCiAgICBwYXJ0aWNpcGFudCBDIGFzIOS4u+WKqOWFs+mXreerrwogICAgcGFydGljaXBhbnQgUyBhcyDooqvliqjlhbPpl63nq68KICAgIEMtPj5TOiBGSU4gc2VxPXUKICAgIFMtLT4+QzogQUNLIGFjaz11KzEKICAgIFMtLT4+QzogRklOIHNlcT13IGFjaz11KzEKICAgIEMtPj5TOiBBQ0sgc2VxPXUrMSBhY2s9dysxCg=="}),e[5]||(e[5]=r('<p>典型状态包括 <code>FIN-WAIT-1/2</code>、<code>CLOSE-WAIT</code>、<code>LAST-ACK</code>、<code>TIME-WAIT</code>。ACK 与 FIN 可能合并，不是所有关闭都固定四个包；不能不看中间发送的数据就把 FIN 序号机械写成 <code>v+1</code>。</p><h3 id="流量控制与拥塞控制" tabindex="-1">流量控制与拥塞控制 <a class="header-anchor" href="#流量控制与拥塞控制" aria-label="Permalink to &quot;流量控制与拥塞控制 {#流量控制与拥塞控制}&quot;">​</a></h3><p>流量控制保护接收端缓冲能力，接收窗口 <code>rwnd</code> 由接收方通告；拥塞控制考虑网络承载能力，发送方通过 <code>cwnd</code> 等状态调节在途数据。发送量同时受两者等因素限制。</p><p>教材中的慢启动、拥塞避免、快速重传与快速恢复是理解经典机制的入口。超时与重复确认触发的处理不同，具体窗口更新取决于算法；不能把所有实现都概括成“降到 1 MSS 再开始”。</p><p>网络层还可通过调度、队列管理、流量调节和准入控制降低拥塞；增加带宽与丢弃负载解决的条件不同。</p><p><span id="第二章-网络应用" aria-hidden="true"></span><span id="_1-计算机网络应用体系结构" aria-hidden="true"></span><span id="_2-网络应用通讯基础原理" aria-hidden="true"></span><span id="_3-域名系统-dns" aria-hidden="true"></span><span id="_4-万维网应用" aria-hidden="true"></span><span id="_5-internet-电子邮件" aria-hidden="true"></span><span id="_6、7-ftp、p2p-应用" aria-hidden="true"></span><span id="_8-socket-编程" aria-hidden="true"></span></p>',6))])}const _=n(l,[["render",s]]);export{g as __pageData,_ as default};
